using System;
using System.Linq;
using CastleFight;
using Newtonsoft.Json.Linq;
using UnityEngine;
public static class OrcCompletionChecks {
    static HumanMatch Fresh(JObject c,int aspect=-1){var m=new HumanMatch((JObject)c.DeepClone(),100000,1,aspect,-1);m.Gold[1]=0;m.Wood[0]=10000;foreach(var l in m.Lines){l.speed=0;l.regen=0;}return m;}
    static HumanMatch.Unit Unit(HumanMatch m,int team,string raw,Vector2 p){var u=m.Spawn(team,m.Kind(raw),p);u.onRoad=true;u.cooldown=10000;u.hp=u.maxHp=10000;return u;}
    static HumanMatch.Hut Building(HumanMatch m,string raw,int x){if(!m.TryBuild(0,m.Kind(raw),x,15,out var e))throw new Exception(e);var h=m.Huts.Last();m.Builders[0].position=h.position-Vector2.up*2.4f;for(int i=0;i<40&&!h.paid;i++)m.Step(.05f);return h;}
    static void Step(HumanMatch m,float sec){for(int i=0;i<(int)Math.Ceiling(sec/.05f);i++)m.Step(.05f);}
    public static void Run(JObject c,Action<bool,string> check) {
        var m=Fresh(c);check(m.BaseKinds.Length==11&&m.Lines.Length==19&&m.Lines.Count(l=>l.Producer)==14&&m.AspectCatalog.Count==2,"complete Orc catalog has 11 base buildings 8 upgrades 14 units and both source aspects");
        check(m.Lines[m.Kind("h02I")].category=="siege"&&m.Lines[m.Kind("h02I")].woodReward==285&&m.Lines[m.Kind("h02N")].incomeRate==.011f&&m.Lines[m.Kind("o000")].incomeRate==.007f,"siege wood and special/tower income use Godot category rates");
        var wyrm=Unit(m,0,"h02P",Vector2.zero);check(m.Flying(wyrm)&&m.Lines[wyrm.kind].unit=="o009"&&wyrm.abilities.Contains("A038"),"Wyvern is a flying source unit with poisoned attack");
        var victim=Unit(m,1,"h029",Vector2.right*2);wyrm.attackTarget=victim.id;wyrm.pendingWeapon=m.Lines[wyrm.kind].weapons[0];wyrm.shotDamage=30;wyrm.strikeLeft=0;m.TickUnit(wyrm,.01f);check(victim.effects.Count==0,"Wyvern poison does not apply before its projectile hits");Step(m,.3f);check(victim.effects.Any(e=>e.id=="A038")&&Math.Abs(m.Stat(victim,"speed")+.2f)<.001f&&Math.Abs(m.Stat(victim,"haste")+.2f)<.001f,"Wyvern hit applies poison and 20 percent attack/move slows");float hp=victim.hp;Step(m,1.1f);check(hp-victim.hp>=3.9f,"Wyvern poison deals periodic source damage");
        m=Fresh(c);var cat=Unit(m,0,"h02I",Vector2.zero);victim=Unit(m,1,"h029",Vector2.right*5);cat.attackTarget=victim.id;cat.pendingWeapon=m.Lines[cat.kind].weapons[0];cat.shotDamage=135;cat.strikeLeft=0;m.TickUnit(cat,.01f);check(m.Shots.Any(s=>s.incendiary)&&m.Fires.Count==0,"catapult launches incendiary artillery without mana or a premature fire");Step(m,.3f);check(m.Fires.Any(f=>f.ability=="A02J")&&m.ArtilleryFires==1,"catapult fire appears at projectile impact");hp=victim.hp;Step(m,1.1f);check(hp-victim.hp>40,"catapult fire deals repeated area damage");
        m=Fresh(c);var hut=Building(m,"h02R",7);var ally=Unit(m,0,"h029",hut.position+Vector2.right);hut.mana=10;m.TickBuilding(hut,.01f);check(m.OrcBlessings==1&&ally.abilities.Contains("A03A")&&ally.abilities.Contains("A03D")&&ally.maxHp==10200&&ally.armor==m.Lines[ally.kind].armor+3&&hut.mana==0,"ritual totem spends mana on permanent attack haste health and armor bonuses");
        hut.mana=10;hut.spellTimers.Clear();m.TickBuilding(hut,.01f);check(ally.maxHp==10200&&ally.armor==m.Lines[ally.kind].armor+3,"repeated ritual bonuses do not stack");
        m=Fresh(c);hut=Building(m,"h02O",7);victim=Unit(m,1,"h029",hut.position+Vector2.right*5);var immune=Unit(m,1,"h029",hut.position+Vector2.right*7);immune.spellResist=1;hut.mana=40;m.TickBuilding(hut,.01f);check(m.OrcStasises==1&&victim.stun==4.5f&&victim.stasisLeft==4.5f&&immune.stun==0&&immune.stasisLeft==0&&victim.hp==10000&&hut.mana==0&&m.LegendaryUsed(0)==1,"stasis spends mana globally stuns without damage excludes immunity and reserves legendary slot");
        m=Fresh(c);hut=Building(m,"h02N",7);victim=Unit(m,1,"h029",hut.position+Vector2.right*10);var near=Unit(m,1,"h02H",hut.position+Vector2.right*12);var friend=Unit(m,0,"h029",victim.position);hut.mana=12;m.TickBuilding(hut,.01f);check(m.OrcAcidShots==1&&victim.effects.Count==0&&hut.mana==0,"acid launches without applying damage early");Step(m,.3f);check(m.OrcAcidImpacts==1&&victim.effects.Any(e=>e.id=="A030")&&near.effects.Any(e=>e.id=="A030")&&friend.effects.Count==0,"acid impact applies to nearby organic enemies only");hp=victim.hp;Step(m,1.1f);check(hp-victim.hp>=29&&m.Stat(victim,"armor")==-5&&Math.Abs(m.Stat(victim,"haste")+.2f)<.001f,"acid deals periodic magic damage and reduces armor and attack speed");
        m=Fresh(c);hut=Building(m,"o000",7);victim=Unit(m,1,"h029",hut.position+Vector2.right*5);Step(m,1);check(victim.effects.Any(e=>e.id=="A020")&&m.Lines[hut.kind].buildingWeapons.Length==2,"tower fires its ground weapon and poisons organic targets");
        m=Fresh(c,0);var killer=Unit(m,0,"h029",Vector2.zero);victim=Unit(m,1,"h029",Vector2.right);m.DamageUnit(victim,100000,0,"chaos",false,true,killer);check(killer.effects.Any(e=>e.id=="aspect_orc_honor"&&e.left==5)&&Math.Abs(m.AttackSpeed(killer)-1.5f)<.001f&&Math.Abs(m.Stat(killer,"incoming")+.1f)<.001f,"Honor aspect grants 5 second haste and damage reduction on an ordinary credited kill");victim=Unit(m,1,"h029",Vector2.right);m.DamageUnit(victim,100000,0,"chaos",false,true,killer);check(killer.effects.Count(e=>e.id=="aspect_orc_honor")==1,"Honor refreshes without stacking");
        m=Fresh(c,1);var shaman=Unit(m,0,"h02B",Vector2.zero);var a=Unit(m,0,"h029",Vector2.right*3);var b=Unit(m,0,"h029",Vector2.right*4);b.hp=5000;check(m.Cast(shaman,"A02M",a.id)&&a.effects.Any(e=>e.id=="A02M")&&b.effects.Any(e=>e.id=="A02M")&&shaman.mana==85&&Math.Abs(shaman.spellTimers["A02M"]-6/1.35f)<.001f,"Shaman support buffs two allies for one mana cost and reduces only inner fire cooldown");
    }
}
